def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    color = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]

    # Fill a missing cell when it lies between two cells of the object
    # on the same straight line.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == color]
        for a, b in zip(cols, cols[1:]):
            if b - a == 2:
                out[r][a + 1] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == color]
        for a, b in zip(rows, rows[1:]):
            if b - a == 2:
                out[a + 1][c] = 2
    return out
